    '.kusi-external-menu a:hover,.kusi-external-menu a.active{color:#fff;border-color:#d96f9d;background:#d96f9d;box-shadow:0 7px 17px rgba(190,76,126,.2);transform:translateY(-1px)}',
    '.kusi-menu-spark{position:fixed;width:var(--size,7px);height:var(--size,7px);pointer-events:none;z-index:10000;background:#fff;filter:drop-shadow(0 0 3px #fff) drop-shadow(0 0 7px rgba(255,255,255,.75));clip-path:polygon(50% 0,62% 36%,100% 50%,62% 64%,50% 100%,38% 64%,0 50%,38% 36%);animation:kusiMenuSpark .78s ease-out forwards}@keyframes kusiMenuSpark{to{opacity:0;transform:translate(var(--x),var(--y)) rotate(140deg) scale(1.25)}}',
    '@media(max-width:820px){.kusi-external-menu{top:auto;right:10px;bottom:10px;left:10px;width:auto;padding:8px;transform:none;display:flex;gap:5px;overflow-x:auto;border-radius:18px}.kusi-external-menu strong{display:none}.kusi-external-menu a{flex:0 0 auto;min-width:82px;margin:0;padding:7px;font-size:12px;white-space:nowrap}}',
